/** A logger the API accepts, backed by the recorder above. */
export function asLogger(recorder: RecordingLogger): Logger {
  const candidate: unknown = recorder;
  if (!isLogger(candidate)) {
    throw new Error('RecordingLogger no longer satisfies the Logger interface.');
  }
  return candidate;
}

function isLogger(value: unknown): value is Logger {
  if (typeof value !== 'object' || value === null) {
    return false;
  }
  const methods = ['trace', 'debug', 'info', 'warn', 'error', 'fatal', 'child'];
  // Read through the prototype chain. `child` is a class method, so it is not an
  // own enumerable property and Object.entries would not see it.
  const record = value as Record<string, unknown>;
  return methods.every((name) => typeof record[name] === 'function');
}
